    private static final int SCENE_GROUP_NAME_MAX_LEN = 256;

    private static final int SCENE_CODE_MAX_LEN = 256;

    private static final int SCENE_DESCRIPTION_MAX_LEN = 256;

    private static final double USER_PENETRATION_RATE_EMPTY_VALUE = -1;

    private static final double USER_PENETRATION_RATE_MIN_VALUE = 0.0d;

    private static final double USER_PENETRATION_RATE_MAX_VALUE = 100.0d;

    private static final int SCENE_MAX_USER_GROUP_SIZE = 10;

    private static final int SCENE_MAX_5QI_LEN = 40;

    private static final int SCENE_MAX_QCI_LEN = 1000;

    private static final int BATCH_SIZE = 100;

    private static final int VENUE_CAPACITY_EMPTY_VALUE = -1;

    private static final int VENUE_CAPACITY_MIN_VALUE = 1;

    private static final int VENUE_CAPACITY_MAX_VALUE = 100000;

    private static final Pattern NR5QI_QCI_REG = Pattern.compile("^\\d+(,\\d+)*$");

    private static final double MIN_THP = 0.0d;

    private static final double MAX_THP = 1000.0d;

    private static final String SCENES_MGR_INVALID_PARAM_MESSAGE = "prs.scenesmgr.invalidParam";

    private static final String SCENES_MGR_SUCCESS = "prs.scenesmgr.success";

    private static final String SCENES_MGR_FAILED = "prs.scenesmgr.failed";

    private static final String SCENE_MANAGE = "prs.scenesmgr.sceneManage";

    private static final String SCENES_MGR_CATEGORY = "prs.scenesmgr.category";

    private static final String SCENES_NUM_LIMIT_PROPERTY_NAME = "liveProvisioningEva.scenes.num.limit";

    private static final String SCENE_CELLS_NUM_LIMIT_PROPERTY_NAME = "liveProvisioningEva.sceneCells.num.limit";

    private static final String[] INVALID_TEXT_CHAR = {"`", "[", "]", "^", "{", "}", "\"", "|", "<", ">", "\\", ","};

    private static final String CELL_RELATED_TYPE_MANUAL = "MANUAL";

    private static final List<String> VENUE_UPDATE_PARAMS = Arrays.asList("toCAllocVenues", "toCAllocIndoorMapInfos");

    private static final int NO_SCENE_CREATING_FLAG = 1;

    private static final String SCENE_CREATE_LOCK = "tocAllocEva.SceneCreateLock";

    @Autowired private ScenesMgrDBMapper scenesMgrDBMapper;

    @Autowired private IParamMgr paramMgr;

    @Autowired private VenueAssuranceDBMapper venueAssuranceDBMapper;

    @Autowired private IPropertyService propertyService;

    @Autowired private ScenesAssuranceDBMapper scenesAssuranceDBMapper;

    @Autowired private SceneTaskManageMapper sceneTaskManageMapper;

    @Autowired private NRAllocEvaService nrAllocEvaService;

    @Autowired private SceneTaskManageDBMapper sceneTaskManageDBMapper;

    @Autowired
    private ILicenseService licenseService;

    /**
     * 服务启动执行的方法
     */
    @PostConstruct
    public void init() {
        try {
            this.updateSceneParam();
        } catch (Throwable e) {
            LOGGER.error("Post construct update scene param error.", e);
        }
    }

    @Override
    public List<Scene> getScenes() throws ServiceException {
        LOGGER.info("getScenes start");
        List<Scene> scenes = scenesMgrDBMapper.getScenes();
        scenes.forEach(this::changeCityCode);
        LOGGER.info("scenes size:{}", scenes.size());
        return scenes;
    }

    @Override
    public Scene getScene(int sceneId) throws ServiceException {
        LOGGER.info("getScene start, sceneId:{}", sceneId);
        Scene scene = scenesMgrDBMapper.getScene(sceneId);
        changeCityCode(scene);
        return scene;
    }

    @Override
    @Transactional
    public void modifyScene(Scene scene) throws ServiceException {
        LOGGER.info("modifyScene start, sceneName:{}, sceneType:{}", scene.getSceneName(), scene.getSceneType());
        try {
            changeCityCode(scene);
            checkScene(scene);
            Scene existingScene = scenesMgrDBMapper.getScene(scene.getSceneId());
            checkSceneNameChange(scene, existingScene);
            checkSceneCodeChange(scene, existingScene);
            checkSceneTypeChange(scene, existingScene);
            checkCityCodeChange(scene, existingScene);
            SceneTypeEnum sceneTypeEnum = SceneTypeEnum.toEnum(scene.getSceneType());
            List<CellInfo> cells = querySceneCells(scene, sceneTypeEnum);
            modifyExistScene(scene, cells);
            writeCreateOrEditOperationLog(scene.getSceneName(), Constants.OPERATION_LEVEL_SUCCESS, false);
            LOGGER.info("modifyScene success.");
        } catch (Exception e) {
            LOGGER.info("modifyScene error.", e);
            writeCreateOrEditOperationLog(scene.getSceneName(), Constants.OPERATION_LEVEL_FAILED, false);
            throw e;
        }
    }

    private synchronized void modifyExistScene(Scene scene, List<CellInfo> cells) throws ServiceException {
        int sceneType = scene.getSceneType();
        SceneTypeEnum sceneTypeEnum = SceneTypeEnum.toEnum(sceneType);
        switch (sceneTypeEnum) {
            case VENUE:
                Scene existScene = scenesMgrDBMapper.getScene(scene.getSceneId());
                if (existScene.getRelateRegionId() != scene.getRelateRegionId()) {
                    venueAssuranceDBMapper.incrementReferenceCount(scene.getRelateRegionId());
                    venueAssuranceDBMapper.reduceReferenceCount(existScene.getRelateRegionId());
                }
                if (CollectionUtils.isNotEmpty(scene.getBackgroundUserGroup())) {
                    scenesMgrDBMapper.updateUserGroups(scene.getSceneId(), scene.getBackgroundUserGroup());
                    List<BackgroundUserGroup> backgroundUserGroup = scene.getBackgroundUserGroup();
                    scenesMgrDBMapper.deleteSceneGroupLabelById(scene.getSceneId()); // 先删除
                    insertUeGroups(scene, backgroundUserGroup);
                }
                scenesMgrDBMapper.updateVenueScene(scene, getVenueInfo(scene));
                HdfsFileUploader.asyncUpload(paramMgr, VENUE_UPDATE_PARAMS);
                break;
            case TRANSPORT_HUB:
                scenesMgrDBMapper.deleteSceneCells(scene.getSceneId());
                saveSceneInfos(cells, scene);
                scenesMgrDBMapper.updateTransportOrSpotScene(scene);
                break;
            case SCENIC_SPOT, OTHER:
                scenesMgrDBMapper.updateTransportOrSpotScene(scene);
                break;
            default:
                LOGGER.error("Invalid sceneType:{}", sceneType);
        }
        if (CollectionUtils.isNotEmpty(scene.getBitPackageInfos())) {
            scenesMgrDBMapper.updateScenePackage(scene.getBitPackageInfos(), scene.getSceneId());
        } else {
            scenesMgrDBMapper.deletePackageBySceneIds(new int[] {scene.getSceneId()});
        }
        this.updateSceneParam();
    }

    private void insertUeGroups(Scene scene, List<BackgroundUserGroup> backgroundUserGroup) {
        IntStream.range(0, backgroundUserGroup.size())
                .forEach(i -> scenesMgrDBMapper.saveSceneGroupLabelsById(
                        scene.getSceneId(), i, backgroundUserGroup.get(i).getUeGroups()));
    }

    private void checkSceneNameChange(Scene scene, Scene existingScene) throws VisibleException {
        if (!existingScene.getSceneName().equals(scene.getSceneName())) {
            checkSceneNameExists(scene.getSceneName());
        }
    }

    private void checkSceneCodeChange(Scene scene, Scene existingScene) throws VisibleException {
        if (!existingScene.getSceneCode().equals(scene.getSceneCode())) {
            // 场景编码不支持修改
            LOGGER.info("existing sceneCode:{}, new sceneCode:{}", existingScene.getSceneCode(), scene.getSceneCode());
            throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.sceneCodeModifyFail"));
        }
    }

    private void checkSceneTypeChange(Scene scene, Scene existingScene) throws VisibleException {
        if (existingScene.getSceneType() != scene.getSceneType()) {
            // 场景类型不支持修改
            LOGGER.info("existing sceneType:{}, new sceneType:{}", existingScene.getSceneType(), scene.getSceneType());
            throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.sceneTypeModifyFail"));
        }
    }

    private void checkCityCodeChange(Scene scene, Scene existingScene) throws VisibleException {
        if (!existingScene.getCityCode().equals(scene.getCityCode())) {
            // 场景所在城市不支持修改
            LOGGER.info("existing cityCode:{}, new cityCode:{}", existingScene.getCityCode(), scene.getCityCode());
            throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.cityCodeModifyFail"));
        }
    }

    private void changeCityCode(Scene scene) {
        if (StringUtils.isEmpty(scene.getCityCode())) {
            // 接口读入的Scene
            scene.setCityCode(DEFAULT_CITY_CODE);
            return;
        }
        if (DEFAULT_CITY_CODE.equals(scene.getCityCode())) {
            // 接口返回的Scene
            scene.setCityCode(null);
        }
    }

    private void checkSceneCellsSize(int cellSize, SceneTypeEnum sceneTypeEnum) throws VisibleException {
        int sceneCellNumLimit = propertyService.getValueByDefault(SCENE_CELLS_NUM_LIMIT_PROPERTY_NAME,
            SCENE_CELLS_NUM_LIMIT);
        LOGGER.info("scene cell size: {}, max cell size: {}", cellSize, sceneCellNumLimit);
        if (cellSize <= sceneCellNumLimit) {
            return;
        }
        String errorMsg = SceneTypeEnum.VENUE == sceneTypeEnum
            ? LocaleUtil.getMessage("prs.scenesmgr.venueCellSizeOverLimit", cellSize, sceneCellNumLimit)
            : LocaleUtil.getMessage("prs.scenesmgr.sceneCellSizeOverLimit", cellSize, sceneCellNumLimit);
        throw new VisibleException(ErrorCode.ERROR, errorMsg);
    }

    private List<CellInfo> querySceneCells(Scene scene, SceneTypeEnum sceneTypeEnum) {
        switch (sceneTypeEnum) {
            case VENUE:
                return venueAssuranceDBMapper.queryVenueCellsByInDoorId(scene.getRelateRegionId());
            case TRANSPORT_HUB, SCENIC_SPOT, OTHER:
                return get2DMapCells(scene);
            default:
                LOGGER.error("Invalid sceneType:{}", scene.getSceneType());
        }
        return Collections.emptyList();
    }

    @Override
    @Transactional
    public synchronized void addScene(Scene scene) throws ServiceException {
        LOGGER.info("addScene start, sceneName:{}, sceneType: {}", scene.getSceneName(), scene.getSceneType());
        String timeStamp = DateTime.now().toString(DateTimeFormat.forPattern("yyyyMMddHHmmss"));
        int lockRes = scenesMgrDBMapper.tryLockSceneTask(SCENE_CREATE_LOCK, timeStamp);
        LOGGER.info("addScene lockRes:{}", lockRes);
        if (lockRes != NO_SCENE_CREATING_FLAG) {
            throw new VisibleException(ErrorCode.ERROR,
                LocaleUtil.getMessage("prs.web.experienceAssurance.scene.task.multiInstance.limit"));
        }
        try {
            changeCityCode(scene);
            checkScenesNumberLimit();
            checkScene(scene);
            checkSceneNameExists(scene.getSceneName());
            checkSceneExists(scene.getSceneType(), scene.getCityCode(), scene.getSceneCode());
            SceneTypeEnum sceneTypeEnum = SceneTypeEnum.toEnum(scene.getSceneType());
            List<CellInfo> cells = querySceneCells(scene, sceneTypeEnum);
            checkSceneCellsSize(cells.size(), sceneTypeEnum);
            createNewScene(scene, cells);
            writeCreateOrEditOperationLog(scene.getSceneName(), Constants.OPERATION_LEVEL_SUCCESS, true);
            LOGGER.info("addScene success.");
        } catch (Exception e) {
            LOGGER.info("addScene error.", e);
            writeCreateOrEditOperationLog(scene.getSceneName(), Constants.OPERATION_LEVEL_FAILED, true);
            throw e;
        } finally {
            scenesMgrDBMapper.tryUnlockSceneTask(SCENE_CREATE_LOCK, timeStamp);
        }
    }

    private synchronized void createNewScene(Scene scene, List<CellInfo> cells) throws VisibleException {
        int sceneType = scene.getSceneType();
        scene.setSceneId(scenesMgrDBMapper.getNewSceneId());
        SceneTypeEnum sceneTypeEnum = SceneTypeEnum.toEnum(sceneType);
        switch (sceneTypeEnum) {
            case VENUE:
                if (CollectionUtils.isNotEmpty(scene.getBackgroundUserGroup())) {
                    scenesMgrDBMapper.saveUserGroups(scene.getSceneId(), scene.getBackgroundUserGroup());
                    List<BackgroundUserGroup> backgroundUserGroup = scene.getBackgroundUserGroup();
                    insertUeGroups(scene, backgroundUserGroup);
                }
                VenueInfo venueInfo = getVenueInfo(scene);
                scenesMgrDBMapper.saveVenueScene(scene, venueInfo);
                venueAssuranceDBMapper.incrementReferenceCount(venueInfo.getIndoorId());
                HdfsFileUploader.asyncUpload(paramMgr, VENUE_UPDATE_PARAMS);
                break;
            case TRANSPORT_HUB, SCENIC_SPOT, OTHER:
                // 新增对区域的引用个数
                LOGGER.info("saveTransportHubScene or SpotScene, sceneId:{}, regionId: {}", scene.getSceneId(),
                    scene.getRelateRegionId());
                saveSceneInfos(cells, scene);
                scenesAssuranceDBMapper.insertRegionRelateScene(scene);
                break;
            default:
                LOGGER.error("Invalid sceneType:{}", sceneType);
        }
        scenesMgrDBMapper.saveScene(scene);
        List<BitPackageInfo> packages = scene.getBitPackageInfos();
        if (CollectionUtils.isNotEmpty(packages)) {
            scenesMgrDBMapper.saveScenePackage(packages, scene.getSceneId());
        }
        this.updateSceneParam();
    }

    private void saveSceneInfos(List<CellInfo> cells, Scene scene) {
        if (CollectionUtils.isEmpty(cells)) {
            return;
        }
        Lists.partition(cells, BATCH_SIZE)
            .forEach(batchCells -> scenesMgrDBMapper.insertSceneCellInfos(scene.getSceneId(), batchCells));
    }

    private List<CellInfo> get2DMapCells(Scene scene) {
        if (CELL_RELATED_TYPE_MANUAL.equals(scenesAssuranceDBMapper.getCellRelatedType(scene.getRelateRegionId()))) {
            return scenesAssuranceDBMapper.getCellInfosByRegionId(scene.getRelateRegionId());
        }
        return sceneTaskManageMapper.getCellInfos(scene.getRelateRegionId());
    }

    private VenueInfo getVenueInfo(Scene scene) {
        VenueInfo venueInfo = new VenueInfo();
        venueInfo.setVenueId(scene.getSceneId());
        venueInfo.setVenueCode(scene.getSceneCode());
        venueInfo.setVenueName(scene.getSceneName());
        venueInfo.setIndoorId(scene.getRelateRegionId());
        venueInfo.setDescription(scene.getDescription());
        venueInfo.setCapacity(scene.getCapacity());
        venueInfo.setUserPenetrationRate(scene.getNrUserPenetrationRate());
        venueInfo.setActiveStatus(1); // 该字段已废弃，赋值为1即默认已激活
        return venueInfo;
    }

    private boolean isLicenseExist(String license) {
        try {
            if (licenseService.checkSingleLicense(license)) {
                return true;
            }
        } catch (Throwable e) {
            LOGGER.error("checkSingleLicense error.", e);
        }
        return false;
    }

    private boolean isEvaLicenseExist() {
        return isLicenseExist(LicenseItems.BIT_SMARTBOARD_LIC);
    }

    private boolean isPreEvaLicenseExist() {
        return isLicenseExist(LicenseItems.NR_ALLOC_EVA_LICENSE);
    }

    private void checkScene(Scene scene) throws VisibleException, WebException {
        LOGGER.info("checkScene isEvaLicenseExist:{}, isPreEvaLicenseExist:{}", isEvaLicenseExist(),
            isPreEvaLicenseExist());
        HtmlUtil.isInputValid(scene.getSceneName(), SCENE_NAME_MAX_LEN, INVALID_TEXT_CHAR, false);
        HtmlUtil.isInputValid(scene.getSceneCode(), SCENE_CODE_MAX_LEN, INVALID_TEXT_CHAR, false);
        HtmlUtil.isInputValid(scene.getDescription(), SCENE_DESCRIPTION_MAX_LEN, INVALID_TEXT_CHAR, true);
        int sceneType = scene.getSceneType();
        if (!SceneTypeEnum.isValidSceneType(sceneType)) {
            // 场景类型不合法
            LOGGER.info("Invalid sceneType:{}", sceneType);
            throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.sceneTypeInvalid"));
        }
        if (SceneTypeEnum.VENUE.getSceneType() == sceneType) {
            int capacity = scene.getCapacity();
            boolean isValidCapacity = capacity >= VENUE_CAPACITY_MIN_VALUE && capacity <= VENUE_CAPACITY_MAX_VALUE;
            boolean isValidEmptyCapacity = isEvaLicenseExist() && capacity == VENUE_CAPACITY_EMPTY_VALUE;
            if (!(isValidCapacity || isValidEmptyCapacity)) {
                // 场馆规模不合法
                LOGGER.info("isEvaLicenseExist:{}, sceneType:{}, invalid capacity:{}", isEvaLicenseExist(), sceneType,
                    scene.getCapacity());
                throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.sceneScaleInvalid"));
            }
            if (!(isEvaLicenseExist() && CollectionUtils.isEmpty(scene.getBackgroundUserGroup()))) {
                checkBackgroundUserGroup(scene);
            }
        }
        if (SceneTypeEnum.VENUE.getSceneType() == sceneType) {
            double userPenetrationRate = scene.getNrUserPenetrationRate();
            boolean isValidRate = userPenetrationRate > USER_PENETRATION_RATE_MIN_VALUE
                && userPenetrationRate <= USER_PENETRATION_RATE_MAX_VALUE;
            boolean isValidEmptyRate = isEvaLicenseExist() && ValueCheckUtils.isDoubleEqual(userPenetrationRate,
                USER_PENETRATION_RATE_EMPTY_VALUE);
            if (!(isValidRate || isValidEmptyRate)) {
                // 5G用户渗透率不合法
                LOGGER.info("Invalid userPenetrationRate:{}", userPenetrationRate);
                throw new VisibleException(ErrorCode.ERROR,
                    LocaleUtil.getMessage("prs.scenesmgr.userPenetrationRateInvalid"));
            }
        }
        if (SceneTypeEnum.TRANSPORT_HUB.getSceneType() == sceneType
            || SceneTypeEnum.SCENIC_SPOT.getSceneType() == sceneType) {
            if (venueAssuranceDBMapper.getRegionCount(scene.getRelateRegionId(),
                RegionCategoryEnum.AREA_MBB.getCategoryId()) <= 0) {
                // 区域信息无效
                LOGGER.info("Invalid relateRegionId:{}, categoryId:{}", scene.getRelateRegionId(),
                    RegionCategoryEnum.AREA_MBB.getCategoryId());
                throw new VisibleException(ErrorCode.ERROR,
                    LocaleUtil.getMessage("prs.scenesmgr.sceneRegionIdInvalid"));
            }
        }
    }

    private void checkScenesNumberLimit() throws VisibleException {
        int size = scenesMgrDBMapper.getScenes().size();
        int realScenesNumLimit = propertyService.getValueByDefault(SCENES_NUM_LIMIT_PROPERTY_NAME, SCENES_NUM_LIMIT);
        if (size >= realScenesNumLimit) {
            // 场景个数已达上限200
            LOGGER.info("Scenes size:{}, realScenesNumLimit:{}", size, realScenesNumLimit);
            throw new VisibleException(ErrorCode.ERROR,
                LocaleUtil.getMessage("prs.scenesmgr.scenesSizeLimit", realScenesNumLimit));
        }
    }

    private void checkSceneNameExists(String sceneName) throws VisibleException {
        if (scenesMgrDBMapper.getSceneNameCount(sceneName) > 0) {
            // 场景名称已存在
            LOGGER.info("Duplicate sceneName:{}", sceneName);
            throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.sceneNameAlreadyExists"));
        }
    }

    private void checkSceneExists(int sceneType, String cityCode, String sceneCode) throws VisibleException {
        if (scenesMgrDBMapper.getSceneCount(sceneType, cityCode, sceneCode) > 0) {
            // 相同的场景已存在
            LOGGER.info("Duplicate sceneCode:{}", sceneCode);
            throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.sceneCodeAlreadyExists"));
        }
    }

    private void checkBackgroundUserGroup(Scene scene) throws VisibleException, WebException {
        List<BackgroundUserGroup> userGroups = scene.getBackgroundUserGroup();
        if (CollectionUtils.isEmpty(userGroups)) {
            throw new VisibleException(ErrorCode.ERROR,
                LocaleUtil.getMessage(SCENES_MGR_INVALID_PARAM_MESSAGE, "backgroundUserGroup"));
        }
        HtmlUtil.validateListLength(userGroups, SCENE_MAX_USER_GROUP_SIZE);
        Set<String> allGroupName = new HashSet<>();
        for (BackgroundUserGroup userGroup : userGroups) {
            String groupName = userGroup.getGroupName();
            HtmlUtil.isInputValid(groupName, SCENE_GROUP_NAME_MAX_LEN, INVALID_TEXT_CHAR, false);
            if (!allGroupName.add(groupName)) {
                // 同一场景id，用户组名不能重复
                LOGGER.info("Duplicate groupName:{}, allGroupName:{}", groupName, allGroupName);
                throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.groupNameDuplicate"));
            }
            // 不填会被强转成0, 上下行速率不能同时留空
            boolean isGmRateInvalid = Stream.of(userGroup.getUlGmRate(), userGroup.getDlGmRate())
                .allMatch(value -> value == 0);
            if (isGmRateInvalid || isThpInvalid(userGroup.getUlGmRate()) || isThpInvalid(userGroup.getDlGmRate())) {
                // 上行速率或者下行速率不合法
                LOGGER.info("Invalid ulGmRate:{}, dlGmRate:{}", userGroup.getUlGmRate(), userGroup.getDlGmRate());
                throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.invalidThpRange"));
            }
        }
    }

    private boolean isThpInvalid(double thp) {
        return thp < MIN_THP || thp > MAX_THP;
    }

    @Override
    public void deleteScenes(String sceneIds) throws ServiceException {
        LOGGER.info("deleteScenes start, sceneIds:{}", sceneIds);
        try {
            if (StringUtils.isEmpty(sceneIds)) {
                throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage(DELETE_SCENEID_EMPTY_ERROR_MESSAGE));
            }
            int[] inputSceneIds = Arrays.stream(sceneIds.trim().split(",")).mapToInt(Integer::valueOf).toArray();
            checkDeleteSceneIds(inputSceneIds);
            List<VenueInfo> venueInfos = scenesMgrDBMapper.getVenuesByIds(inputSceneIds);
            scenesMgrDBMapper.deleteSceneByIds(inputSceneIds);
            scenesMgrDBMapper.deleteSceneBySceneIds(inputSceneIds);
            scenesMgrDBMapper.deletePackageBySceneIds(inputSceneIds);
            this.updateSceneParam();
            if (CollectionUtils.isNotEmpty(venueInfos)) {
                HdfsFileUploader.asyncUpload(paramMgr, VENUE_UPDATE_PARAMS);
                for (VenueInfo venueInfo : venueInfos) {
                    venueAssuranceDBMapper.reduceReferenceCount(venueInfo.getIndoorId());
                }
            }
            scenesAssuranceDBMapper.deleteRegionRelateScene(inputSceneIds);
            writeDeleteOperationLog(Constants.OPERATION_LEVEL_SUCCESS);
            LOGGER.info("deleteScenes success.");
        } catch (Exception e) {
            LOGGER.info("deleteScenes fail.", e);
            writeDeleteOperationLog(Constants.OPERATION_LEVEL_FAILED);
            throw ExceptionUtils.onError(e);
        }
    }

    private void checkDeleteSceneIds(int[] sceneIds) throws VisibleException {
        if (sceneIds == null || sceneIds.length == 0) {
            throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage(DELETE_SCENEID_EMPTY_ERROR_MESSAGE));
        }
        int realScenesNumLimit = propertyService.getValueByDefault(SCENES_NUM_LIMIT_PROPERTY_NAME, SCENES_NUM_LIMIT);
        if (sceneIds.length > realScenesNumLimit) {
            LOGGER.info("sceneIds length:{}, realScenesNumLimit:{}", sceneIds.length, realScenesNumLimit);
            throw new VisibleException(ErrorCode.ERROR,
                LocaleUtil.getMessage("prs.scenesmgr.deleteSceneOverLimit", realScenesNumLimit));
        }
        List<Scene> allReferenceScenes = scenesMgrDBMapper.getAllReferenceScenes(sceneIds);
        if (CollectionUtils.isNotEmpty(allReferenceScenes)) {
            // 当场景存在关联的预估/评估任务时，该场景不能删除。提示该场景已被使用，请删除相关任务后重试。
            List<String> sceneNames = allReferenceScenes.stream().map(Scene::getSceneName).toList();
            LOGGER.info("allReferenceScenes name:{}", sceneNames);
            throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.inUse"));
        }
    }

    private void writeDeleteOperationLog(int result) {
        String operation = LocaleUtil.getMessage("prs.scenesmgr.deleteScene");
        String opResult = (result == Constants.OPERATION_LEVEL_SUCCESS
            ? LocaleUtil.getMessage(SCENES_MGR_SUCCESS)
            : LocaleUtil.getMessage(SCENES_MGR_FAILED));
        LogInfo logInfo = new LogInfo(operation, operation + opResult, LocaleUtil.getMessage(SCENE_MANAGE),
            LocaleUtil.getMessage(SCENES_MGR_CATEGORY), result);
        OperationLogWriter.writeOperationLog(logInfo, AuditLogLevel.MAJOR.getValue(), OperationType.DELETE,
            AuditModule.MODULE_REPORT);
    }

    private void writeCreateOrEditOperationLog(String venueName, int result, boolean isAdd) {
        String operation = isAdd
            ? LocaleUtil.getMessage("prs.scenesmgr.creatScene")
            : LocaleUtil.getMessage("prs.scenesmgr.editScene");
        String opResult = (result == Constants.OPERATION_LEVEL_SUCCESS
            ? LocaleUtil.getMessage(SCENES_MGR_SUCCESS)
            : LocaleUtil.getMessage(SCENES_MGR_FAILED));
        String detail = String.join(" ", operation, venueName, opResult);
        LogInfo logInfo = new LogInfo(operation, detail, LocaleUtil.getMessage(SCENE_MANAGE),
            LocaleUtil.getMessage(SCENES_MGR_CATEGORY), result);
        OperationLogWriter.writeOperationLog(logInfo, AuditLogLevel.MAJOR.getValue(),
            isAdd ? OperationType.NEW : OperationType.MODIFY, AuditModule.MODULE_REPORT);
    }

    private void updateSceneParam() throws VisibleException {
        HdfsFileUploader.asyncUpload(paramMgr,
            Arrays.asList("activePackage", "sceneInfo", "genericVenueCells", "sceneBkgUsers", "scenePackages"));
        LOGGER.info("updateSceneParam success.");
    }
