package com.huawei.oss.wireless.experienceassuranceservice.common.impl.utils;

import com.huawei.bsp.log.OssLog;
import com.huawei.bsp.log.OssLogFactory;
import com.huawei.bsp.remoteservice.exception.ServiceException;
import com.huawei.maos.commons.deploy.EnvUtil;
import com.huawei.maos.commons.text.StringUtil;
import com.huawei.oss.rest.util.RestCaller;
import com.huawei.oss.rest.util.RestMethod;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Optional;

/**
 * 实例工具类
 *
 * @since 2025/09/10
 */
public class InstanceUtils {
    private static final OssLog LOGGER = OssLogFactory.getLogger(InstanceUtils.class);

    private static final String POLICY_URI = "/rest/oss/inner/experienceassurance/v1/policy";

    private static final String HEADER_BACKEND_LIST_POLICY = "XX-Backend-List-Policy";

    private static final String HEADER_BACKEND_LIST_POLICY_VALUE = "instanceOnly";

    private static final String HEADER_BACKEND_LIST = "Xx-Backend-List";

    private static final String POD_NAME = "POD_NAME";

    private static final String ALL_PREFIX = "all=";

    private static final String SEPARATOR = ",";

    private static final String DASH = "-";

    /**
     * 查询所有实例ID
     *
     * @return 所有实例ID列表
     */
    public static List<Integer> queryAllInstanceIds() {
        try {
            RestCaller<VoidType> restCaller = RestCaller
                .builder(RestMethod.POST, POLICY_URI)
                .addHeader(HEADER_BACKEND_LIST_POLICY, HEADER_BACKEND_LIST_POLICY_VALUE)
                .build();
            Object response = restCaller.execute();
            String backendList = (String) ((java.util.Map<String, Object>) response).get(HEADER_BACKEND_LIST);
            return parseAllInstanceIds(backendList);
        } catch (ServiceException e) {
            LOGGER.error("queryAllInstanceIds failed with ServiceException", e);
            return Collections.emptyList();
        } catch (Exception e) {
            LOGGER.error("queryAllInstanceIds failed with unexpected exception", e);
            return Collections.emptyList();
        }
    }

    /**
     * 查询当前实例ID
     *
     * @return 当前实例ID
     */
    public static Optional<Integer> queryCurrentInstanceId() {
        String podName = EnvUtil.getEnv(POD_NAME);
        if (StringUtil.isEmpty(podName)) {
            return Optional.empty();
        }
        return parseInstanceId(podName);
    }

    /**
     * 解析实例名称获取整数ID
     *
     * @param instanceName 实例名称
     * @return 实例ID
     */
    private static Optional<Integer> parseInstanceId(String instanceName) {
        if (StringUtil.isEmpty(instanceName)) {
            return Optional.empty();
        }
        String[] parts = instanceName.split(DASH);
        if (parts.length == 0) {
            return Optional.empty();
        }
        String lastPart = parts[parts.length - 1];
        if (StringUtil.isEmpty(lastPart)) {
            return Optional.empty();
        }
        try {
            return Optional.of(Integer.parseInt(lastPart));
        } catch (NumberFormatException e) {
            LOGGER.warn("parseInstanceId failed, instanceName: {}", instanceName);
            return Optional.empty();
        }
    }

    private static List<Integer> parseAllInstanceIds(String backendList) {
        if (backendList == null || !backendList.startsWith(ALL_PREFIX)) {
            return Collections.emptyList();
        }
        String instancesStr = backendList.substring(ALL_PREFIX.length());
        return Arrays.stream(instancesStr.split(SEPARATOR))
            .map(String::trim)
            .flatMap(InstanceUtils::parseInstanceIdOpt)
            .collect(java.util.stream.Collectors.toList());
    }

    private static java.util.stream.Stream<Integer> parseInstanceIdOpt(String instance) {
        Optional<Integer> id = parseInstanceId(instance);
        return id.isPresent() ? java.util.stream.Stream.of(id.get()) : java.util.stream.Stream.empty();
    }
}
